package com.zerostreams.app;
import android.app.AlertDialog;import android.content.*;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.json.*;import java.io.*;import java.util.concurrent.atomic.*;
public class DownloadDeletionUiTest {
 @Test public void remoteCancelAndConfirmedDeleteAffectOnlyTheSelectedVideo()throws Exception{Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(context.getCacheDir(),"delete-ui-"+System.nanoTime());Assert.assertTrue(root.mkdirs());File file=new File(root,"Fixture.mp4");try(FileOutputStream output=new FileOutputStream(file)){output.write(new byte[1024]);}DirectDownloads before=DirectDownloads.instance;DirectDownloads manager=new DirectDownloads(context,root,j->"https://fixture.invalid/",(u,o,v)->{throw new IOException("Fixture must not fetch");});JSONObject row=new JSONObject().put("id","delete-ui").put("title","Fixture Movie").put("type","movie").put("state","completed").put("file",file.toString()).put("bytes",1024);manager.jobs.add(row);manager.save();DirectDownloads.instance=manager;AtomicReference<AlertDialog> dialog=new AtomicReference<>();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(context,MainActivity.class))){scenario.onActivity(a->{a.open("Downloads");dialog.set(a.confirmDeleteDownload(row));});scenario.onActivity(a->Assert.assertTrue(dialog.get().getButton(AlertDialog.BUTTON_NEGATIVE).hasFocus()));InstrumentationRegistry.getInstrumentation().sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);InstrumentationRegistry.getInstrumentation().waitForIdleSync();Assert.assertTrue("Cancel preserves the actual file",file.isFile());scenario.onActivity(a->dialog.set(a.confirmDeleteDownload(row)));InstrumentationRegistry.getInstrumentation().waitForIdleSync();scenario.onActivity(a->{dialog.get().getButton(AlertDialog.BUTTON_POSITIVE).requestFocus();Assert.assertTrue(dialog.get().getButton(AlertDialog.BUTTON_POSITIVE).hasFocus());});InstrumentationRegistry.getInstrumentation().sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);InstrumentationRegistry.getInstrumentation().waitForIdleSync();Assert.assertFalse("Delete Video removes the actual file",file.exists());Assert.assertEquals(0,manager.list().length());}finally{DirectDownloads.instance=before;manager.worker.shutdownNow();File[] children=root.listFiles();if(children!=null)for(File child:children)child.delete();root.delete();}}
}
